  Hypothesis Hok : store_ok ASEGS M0 (Z_to_bv 64 (s - 16)) 16%nat = true.
  Hypothesis HLOFF : rdn ASEGS M0 (0x165178 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x10)).
  Hypothesis HCNT : rdn ASEGS M0 (0x6a18a0 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 1)).
