  Theorem cxi_run : forall regs,
    getr regs 10 = Z_to_bv 64 f -> getr regs 11 = Z_to_bv 64 arg -> getr regs 2 = sp -> getr regs 1 = ra -> getr regs 4 = (0x6a1890 : word) ->
    exists regs' M1,
