      /\ mem_grows M0 M1 /\ (forall x : word, ~ cxi_fp (bv_unsigned x) -> M1 x = M0 x)
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6c18e0 + 32 + 8 * n)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 f))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6c18e0 + 288 + 8 * n)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 arg))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6c18e0 + 32 + 8 * (n + 1))) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x76918))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6c18e0 + 288 + 8 * (n + 1))) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6c18e0 + 8)) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 (n + 2)))
      /\ rdn ASEGS M1 (0x6a18a0 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0))
      /\ getr regs' 10 = Z_to_bv 64 0 /\ keeps_cs regs regs'.
